"""Content for the sequential robotics tutorial ("Учебник").

This is hand-authored course data, kept separate from `learning.py`
(the free-form reference library, "Справочник"). Modules are ordered;
lessons inside a module are ordered; the tutorial is meant to be taken
top to bottom, unlike the reference which is browsed by topic.

NOTE: this currently covers the first modules of the full program
(orientation -> Python fundamentals -> OOP in Python -> serial
communication -> Arduino). Further modules (C++ OOP, Raspberry Pi,
SQL, Docker, architecture, computer vision, STM32, capstone) follow the
exact same `CurriculumModule` / `CurriculumLesson` / `CurriculumTask`
shape and can be appended below without touching any other file.
"""

