                    "Отправлять каждый кадр в облако для задач, требующих быстрой реакции — сетевая задержка может оказаться неприемлемой именно там, где скорость реакции критична.",
                    "Смешивать стадии пайплайна в одну неразделимую функцию — это усложняет замену, например, алгоритма детекции без переписывания всего кода целиком.",
