                    "Считать VPN способом добиться полной анонимности — VPN-провайдер видит весь ваш трафик, вы лишь переносите доверие с одной стороны на другую.",
                    "Полагать, что VPN защищает от всего подряд — например, залогинившись на сайте под своим именем через VPN, вы всё равно идентифицированы этим сайтом.",
