ALL_LESSONS: list[CurriculumLesson] = [
    lesson for module in MODULES for lesson in sorted(module.lessons, key=lambda l: l.order)
]

MODULES_SORTED: list[CurriculumModule] = sorted(MODULES, key=lambda m: m.order)


def flat_lesson_sequence() -> list[tuple[CurriculumModule, CurriculumLesson]]:
    """Global (module, lesson) order used for lock/unlock and prev/next."""
    pairs: list[tuple[CurriculumModule, CurriculumLesson]] = []
    for module in MODULES_SORTED:
        for lesson in sorted(module.lessons, key=lambda l: l.order):
            pairs.append((module, lesson))
    return pairs


LESSON_INDEX: dict[str, CurriculumLesson] = {lesson.id: lesson for lesson in ALL_LESSONS}
MODULE_INDEX: dict[str, CurriculumModule] = {module.id: module for module in MODULES_SORTED}
LESSON_MODULE: dict[str, str] = {
    lesson.id: module.id for module in MODULES_SORTED for lesson in module.lessons
}
